  ('acfe5235-536e-5f93-9a91-bfb6b0b96fa7', null, (select id from public.skills where slug = 'read-g7-argument-evidence'), null, 'hard',
   $q$Which statement best evaluates whether the author's evidence is sufficient?$q$, $q$[{"text":"The evidence is sufficient only because a teacher agreed with it, since teachers are always right.","is_correct":false,"misconception_token":"appeal-to-authority"},{"text":"The evidence is useless, because a study about volcanoes cannot tell us anything about studying.","is_correct":false,"misconception_token":"misjudges-relevance"},{"text":"The evidence is complete, because one study proves the method works for every student and subject.","is_correct":false,"misconception_token":"overgeneralizes"},{"text":"The study gives strong support, but more studies with other subjects would make the claim more convincing.","is_correct":true}]$q$::jsonb, $q$The study gives strong support, but more studies with other subjects would make the claim more convincing.$q$, $q$The study is a fair comparison with clear results, but it used one article and one group of students, so further studies would strengthen the claim. Saying one study proves it for everyone overstates what the evidence shows.$q$, 'draft', '7b3d51ac-2729-566d-8092-73d5770ad2eb')
